const lockPackage = `-- name: LockPackage :one
SELECT id
FROM package
WHERE id = $1
    FOR UPDATE
`

// Bloquea el PKG hasta el fin de la transacción: las firmas de un checklist y la revisión de un DIAG
// son de solo inserción, así que lo que se bloquea es la fila del PKG al que pertenecen.
func (q *Queries) LockPackage(ctx context.Context, id uuid.UUID) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, lockPackage, id)
	var id_2 uuid.UUID
	err := row.Scan(&id_2)
	return id_2, err
}

const nextCode = `-- name: NextCode :one
INSERT INTO code_sequence (prefix, year, last_value)
VALUES ($1, $2, 1)
ON CONFLICT (prefix, year) DO UPDATE SET last_value = code_sequence.last_value + 1
RETURNING last_value
`

type NextCodeParams struct {
	Prefix string
	Year   int32
}

func (q *Queries) NextCode(ctx context.Context, arg NextCodeParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextCode, arg.Prefix, arg.Year)
	var last_value int32
	err := row.Scan(&last_value)
	return last_value, err
}

const nextTemplateVersion = `-- name: NextTemplateVersion :one
SELECT (coalesce(max(t.version), 0) + 1)::integer AS version
FROM checklist_template t
         JOIN system_under_test s ON s.id = t.system_id
WHERE s.key = $1
`

func (q *Queries) NextTemplateVersion(ctx context.Context, key string) (int32, error) {
	row := q.db.QueryRow(ctx, nextTemplateVersion, key)
	var version int32
	err := row.Scan(&version)
	return version, err
}
